import numpy as np

def make_state(agent=None, moving=None, reward=None, obstacle=None, prev=None):
    x = np.zeros(500)
    def setcell(g, r, c):
        x[(r*10+c)*5 + g] = 1.0
    # wall border is always in ch3
    for r in range(10):
        for c in range(10):
            if r in (0, 9) or c in (0, 9):
                setcell(3, r, c)
    for cells, g in [(agent, 0), (moving, 1), (reward, 2), (obstacle, 3), (prev, 4)]:
        if cells:
            for (r, c) in cells:
                setcell(g, r, c)
    return x

configs, labels = [], []
# obstacle directly in the left path vs right path
for lab, obst in [("none", None), ("left(5,4)", [(5, 4)]), ("right(5,6)", [(5, 6)])]:
    configs.append(make_state(agent=[(5, 5)], obstacle=obst))
    labels.append("agent(5,5) obstacle " + lab)
# agent near the left wall / middle / right wall
for col in [1, 4, 8]:
    configs.append(make_state(agent=[(5, col)]))
    labels.append(f"agent(5,{col}) no objects")
# Breakout-like: paddle at bottom-left, ball upper-right moving left vs upper-left
configs.append(make_state(agent=[(8, 1)], moving=[(4, 6)], prev=[(4, 7)]))
labels.append("paddle(8,1) ball upper-right")
configs.append(make_state(agent=[(8, 1)], moving=[(4, 2)], prev=[(4, 1)]))
labels.append("paddle(8,1) ball upper-left")
configs.append(make_state(agent=[(8, 1)], moving=[(4, 6)], prev=[(4, 7)], reward=[(2, 6), (2, 7)]))
labels.append("paddle(8,1) ball upper-right + bricks")

X = np.array(configs)
out = forward(X)   # single forward pass, batch of 9
for lab, lg in zip(labels, out):
    a = int(np.argmax(lg))
    print(f"{lab:40s} action={a}  logits={np.round(lg, 2)}")
